window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d1d6de64999855b4"]={"versions": [{"id": "FIG-d1d6de64999855b4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Modellierungs- und Datenflussdiagramm im Kontext des AUTOSAR-Werkzeug- und Datenaustauschs (Methodology &amp; Templates / Tool Interoperability). Dargestellt wird das Szenario des nebenläufigen Modellierens („Concurrent modeling - updating of elements“) mit Modellaustausch, Aktualisierung und Zusammenführung (Merge) über zwei organisatorische Domänen (Swimlanes / Verantwortungsbereiche „party X“ und „Party Y“) hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei horizontale Verantwortungsbereiche:</p>\n<ul class=\"fig-list\"><li><strong>party X</strong> (Modellurheber / Quellpartei):\n<ul class=\"fig-list\"><li>Paket <code>Model A [source]</code> mit dem Element <code>BrakControl[source]</code>\n</li><li>Prozessschritt / Aktion <code>Update</code> (abgerundetes Rechteck)\n</li><li>Paket <code>Model A [updated]</code> mit dem umbenannten/korrigierten Element <code>BrakeControl [updated]</code>\n</li></ul>\n</li><li><strong>Party Y</strong> (Modellnutzer / Zielpartei):\n<ul class=\"fig-list\"><li>Ursprünglicher Zustand: Paket <code>Model A [remote]</code> mit <code>BrakControl [remote]</code>, verbunden über eine Assoziationslinie mit Element <code>X</code> im Paket <code>Model B</code>\n</li><li>Zusammengeführter Zustand: Paket <code>Model A [merged]</code> mit <code>BrakeControl [merged]</code>, verbunden mit Element <code>X [merged]</code> im Paket <code>Model B [merged]</code>\n</li></ul>\n</li><li><strong>Beziehungen / Schnittstellen:</strong>\n<ul class=\"fig-list\"><li>Gestrichelte Abhängigkeitspfeile von <code>Model A [source]</code> zu <code>Update</code> und von <code>Update</code> zu <code>Model A [updated]</code>\n</li><li>Vertikale Traceability-Beziehungen (<code>«trace»</code>, gestrichelte Pfeile) von <code>Model A [source]</code> zu <code>Model A [remote]</code> sowie von <code>Model A [updated]</code> zu <code>Model A [merged]</code>\n</li><li>Durchgezogene Assoziationskanten zwischen den Elementen aus Model A und Model B (<code>BrakControl [remote]</code> zu <code>X</code> bzw. <code>BrakeControl [merged]</code> zu <code>X [merged]</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Party X erstellt <code>Model A [source]</code> mit Modellelement <code>BrakControl[source]</code>.\n</li><li>Das Modell wird an Party Y übergeben (abgebildet als <code>«trace»</code> nach <code>Model A [remote]</code>).\n</li><li>Party Y bindet das empfangene Element <code>BrakControl [remote]</code> an das eigene Modellelement <code>X</code> in <code>Model B</code> an.\n</li><li>Parallel dazu führt Party X eine Fehlerbehebung bzw. Aktualisierung durch (<code>Update</code>), wodurch das Element zu <code>BrakeControl [updated]</code> in <code>Model A [updated]</code> wird (Tippfehlerkorrektur <code>BrakControl</code> zu <code>BrakeControl</code>).\n</li><li>Party X stellt <code>Model A [updated]</code> an Party Y bereit (zweite <code>«trace»</code>-Beziehung).\n</li><li>Party Y führt einen Merge durch: <code>Model A [merged]</code> enthält das aktualisierte <code>BrakeControl [merged]</code>. Die bestehende Referenz aus <code>Model B [merged]</code> (Element <code>X [merged]</code>) muss auf das aktualisierte Element nachgezogen werden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht konzeptionell die Anforderungen an Werkzeuge zur AUTOSAR-Modellzusammenführung (Model Merge Tooling). Da AUTOSAR-Elemente primär über ihren <code>shortName</code> und den daraus resultierenden vollqualifizierten Pfad identifiziert werden, führt eine Umbenennung oder Korrektur eines Namens bei paralleler Weiterentwicklung zu Referenzbrüchen („dangling references“) in abhängigen Modellen (<code>Model B</code>). Werkzeugketten müssen Mechanismen zur Identitätsverfolgung (z. B. UUIDs oder Heuristiken) und Konfliktauflösung bereitstellen, um Referenzen nach Modellaktualisierungen automatisiert oder assistiert zu reparieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-32b4435a1d5d30ec", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Modellierungs- und Datenflussdiagramm im Kontext des AUTOSAR-Werkzeug- und Datenaustauschs (Methodology &amp; Templates / Tool Interoperability). Dargestellt wird das Szenario des nebenläufigen Modellierens („Concurrent modeling - updating of elements“) mit Modellaustausch, Aktualisierung und Zusammenführung (Merge) über zwei organisatorische Domänen (Swimlanes / Verantwortungsbereiche „party X“ und „Party Y“) hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei horizontale Verantwortungsbereiche:</p>\n<ul class=\"fig-list\"><li><strong>party X</strong> (Modellurheber / Quellpartei):\n<ul class=\"fig-list\"><li>Paket <code>Model A [source]</code> mit dem Element <code>BrakControl[source]</code>\n</li><li>Prozessschritt / Aktion <code>Update</code> (abgerundetes Rechteck)\n</li><li>Paket <code>Model A [updated]</code> mit dem umbenannten/korrigierten Element <code>BrakeControl [updated]</code>\n</li></ul>\n</li><li><strong>Party Y</strong> (Modellnutzer / Zielpartei):\n<ul class=\"fig-list\"><li>Ursprünglicher Zustand: Paket <code>Model A [remote]</code> mit <code>BrakControl [remote]</code>, verbunden über eine Assoziationslinie mit Element <code>X</code> im Paket <code>Model B</code>\n</li><li>Zusammengeführter Zustand: Paket <code>Model A [merged]</code> mit <code>BrakeControl [merged]</code>, verbunden mit Element <code>X [merged]</code> im Paket <code>Model B [merged]</code>\n</li></ul>\n</li><li><strong>Beziehungen / Schnittstellen:</strong>\n<ul class=\"fig-list\"><li>Gestrichelte Abhängigkeitspfeile von <code>Model A [source]</code> zu <code>Update</code> und von <code>Update</code> zu <code>Model A [updated]</code>\n</li><li>Vertikale Traceability-Beziehungen (<code>«trace»</code>, gestrichelte Pfeile) von <code>Model A [source]</code> zu <code>Model A [remote]</code> sowie von <code>Model A [updated]</code> zu <code>Model A [merged]</code>\n</li><li>Durchgezogene Assoziationskanten zwischen den Elementen aus Model A und Model B (<code>BrakControl [remote]</code> zu <code>X</code> bzw. <code>BrakeControl [merged]</code> zu <code>X [merged]</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Party X erstellt <code>Model A [source]</code> mit Modellelement <code>BrakControl[source]</code>.\n</li><li>Das Modell wird an Party Y übergeben (abgebildet als <code>«trace»</code> nach <code>Model A [remote]</code>).\n</li><li>Party Y bindet das empfangene Element <code>BrakControl [remote]</code> an das eigene Modellelement <code>X</code> in <code>Model B</code> an.\n</li><li>Parallel dazu führt Party X eine Fehlerbehebung bzw. Aktualisierung durch (<code>Update</code>), wodurch das Element zu <code>BrakeControl [updated]</code> in <code>Model A [updated]</code> wird (Tippfehlerkorrektur <code>BrakControl</code> zu <code>BrakeControl</code>).\n</li><li>Party X stellt <code>Model A [updated]</code> an Party Y bereit (zweite <code>«trace»</code>-Beziehung).\n</li><li>Party Y führt einen Merge durch: <code>Model A [merged]</code> enthält das aktualisierte <code>BrakeControl [merged]</code>. Die bestehende Referenz aus <code>Model B [merged]</code> (Element <code>X [merged]</code>) muss auf das aktualisierte Element nachgezogen werden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht konzeptionell die Anforderungen an Werkzeuge zur AUTOSAR-Modellzusammenführung (Model Merge Tooling). Da AUTOSAR-Elemente primär über ihren <code>shortName</code> und den daraus resultierenden vollqualifizierten Pfad identifiziert werden, führt eine Umbenennung oder Korrektur eines Namens bei paralleler Weiterentwicklung zu Referenzbrüchen („dangling references“) in abhängigen Modellen (<code>Model B</code>). Werkzeugketten müssen Mechanismen zur Identitätsverfolgung (z. B. UUIDs oder Heuristiken) und Konfliktauflösung bereitstellen, um Referenzen nach Modellaktualisierungen automatisiert oder assistiert zu reparieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d1d6de64999855b4", "to": "FIG-32b4435a1d5d30ec", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
